<?php $issued=$_SESSION['issued_code']??'';unset($_SESSION['issued_code']);if($issued):?><section class="panel"><div class="panel-heading"><h2>Copy your private code</h2><span class="badge success">Shown once</span></div><div class="composer-body"><code class="unlock-code"><?=h($issued)?></code><p>Save this somewhere private. Only its hash is stored. Share it with the player you want to reward.</p></div></section><?php endif?>
<section class="panel"><div class="panel-heading"><h2>Create an unlock code</h2><span class="badge">Admin only</span></div><form method="post" class="composer-body"><?php admin_csrf()?><input type="hidden" name="action" value="code_create"><label>Cosmetic<select name="cosmetic" required><?php foreach($catalog as $id=>$item):?><option value="<?=h($id)?>"><?=h($item['name'])?></option><?php endforeach?></select></label><label>Private label<input name="label" maxlength="80" placeholder="Giveaway, player reward, event…"></label><div class="duration-row"><label>Total uses<input name="maximum" type="number" value="1" min="0" max="100000" required><small>1 = one player · 0 = unlimited players</small></label><label>Expires after (days)<input name="days" type="number" value="0" min="0" max="3650" required><small>0 = no expiry</small></label></div><div class="form-footer"><p>Codes never appear in the public catalogue or client files.<br>Each cosmetic can be unlocked once per account.</p><button class="primary">Generate private code</button></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Issued codes</h2><span class="badge"><?=count($dashboard['codes'])?> most recent</span></div><div class="table-wrap"><table><thead><tr><th>Cosmetic / label</th><th>Uses</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($dashboard['codes'] as $code):$active=(int)$code['active']&&($code['expires_at']===null||(int)$code['expires_at']>time())&&((int)$code['maximum']===0||(int)$code['uses']<(int)$code['maximum']);?><tr><td><strong><?=h($catalog[$code['cosmetic']]['name']??$code['cosmetic'])?></strong><br><small>#<?=h((string)$code['id'])?> · <?=h($code['label'])?></small></td><td><?=h((string)$code['uses'])?> / <?=(int)$code['maximum']===0?'Unlimited':h((string)$code['maximum'])?></td><td><span class="badge <?=$active?'success':'muted'?>"><?=$active?'Available':'Inactive / used'?></span></td><td><?php if((int)$code['active']):?><form method="post"><?php admin_csrf()?><input type="hidden" name="action" value="code_disable"><input type="hidden" name="code_id" value="<?=h((string)$code['id'])?>"><button>Disable</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><p class="hint">Code text cannot be recovered. Generate a new one if you lose it. Disabling a code prevents future redemptions.</p></section>
